"use client";

import React, { useState } from "react";
import { AlertCircle, RefreshCw } from "lucide-react";

export function CheckoutFailedPaymentCard() {
  const [retrying, setRetrying] = useState(false);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-red-500/20 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center gap-1.5 mb-3">
        <AlertCircle className="w-4 h-4 text-red-400" />
        <span className="text-xs font-bold uppercase tracking-wider text-red-400">Payment Failed</span>
      </div>

      <p className="text-xs text-muted-foreground/80 leading-normal mb-4">
        Your transaction was declined by bank gateway. Reasons may include insufficient credit bounds or token expiration.
      </p>

      <button 
        onClick={() => {
          setRetrying(true);
          setTimeout(() => setRetrying(false), 1200);
        }}
        className="w-full py-2 bg-red-600 hover:bg-red-500 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1.5 transition-all"
      >
        <RefreshCw className={`w-3.5 h-3.5 ${retrying ? "animate-spin" : ""}`} />
        <span>{retrying ? "Re-processing payment..." : "Retry Secure payment"}</span>
      </button>
    </div>
  );
}
